package com.osatks.mizan.core

import kotlinx.datetime.LocalDate

/** التقويم الهجري وفق أم القرى من 1300 إلى 1600 هـ (الجدول مأخوذ من java.time.chrono.HijrahChronology). أسماء الأشهر في ملفات اللغة. */
data class HDate(val y: Int, val m: Int, val d: Int)

object Hijri {
    private const val FIRST_YEAR = 1300
    private const val LAST_YEAR = 1600
    /** يوم 1 محرم 1300 بعدد الأيام منذ 1970-01-01 */
    private const val EPOCH_START = -31826L

    /** طول كل شهر من محرم 1300 إلى ذي الحجة 1600: 1 = ثلاثون يوماً، 0 = تسعة وعشرون */
    private const val LENGTHS = ""

    /** بداية كل شهر بعدد الأيام منذ 1970 (عنصر إضافي في الآخر لنهاية الجدول) */
    private val starts: LongArray by lazy {
        val a = LongArray(LENGTHS.length + 1)
        a[0] = EPOCH_START
        for (i in LENGTHS.indices) a[i + 1] = a[i] + if (LENGTHS[i] == '1') 30 else 29
        a
    }

    fun toHijri(date: LocalDate): HDate? {
        val day = date.toEpochDay()
        val s = starts
        if (day < s[0] || day >= s[s.size - 1]) return null
        var lo = 0; var hi = s.size - 2
        while (lo < hi) { val mid = (lo + hi + 1) / 2; if (s[mid] <= day) lo = mid else hi = mid - 1 }
        return HDate(FIRST_YEAR + lo / 12, lo % 12 + 1, (day - s[lo]).toInt() + 1)
    }

    private fun index(y: Int, m: Int): Int? = if (y in FIRST_YEAR..LAST_YEAR && m in 1..12) (y - FIRST_YEAR) * 12 + (m - 1) else null

    fun toGregorian(y: Int, m: Int, d: Int): LocalDate? {
        val i = index(y, m) ?: return null
        if (d < 1 || d > monthLength(y, m)) return null
        return LocalDate.ofEpochDay(starts[i] + d - 1)
    }

    fun monthLength(y: Int, m: Int): Int = index(y, m)?.let { if (LENGTHS[it] == '1') 30 else 29 } ?: 30
}
